// Generates the files that Obsidian cannot translate at run time (Bases names, the note
// template, the statistics note) from one source, the locale files and config.json.
//
//   node tools/build/build-localized.mjs           write the files
//   node tools/build/build-localized.mjs --check   fail if a generated file is missing or outdated
//
//   node tools/build/build-localized.mjs --config path/to/config.json --out path/to/folder
//       generate the files for another config.json (your own statuses, formats and categories)
//       into a folder of your choice. The repository files are not touched in this mode.
//
// Output, per language code:
//   example-vault/Colophon/localized/Library.<code>.base
//   example-vault/Colophon/localized/Book.<code>.md
//   example-vault/Colophon/localized/Statistics.<code>.md
//   example-vault/Colophon/localized/Import.<code>.md
//   example-vault/Colophon/localized/Summaries.<code>.base
//   example-vault/Colophon/localized/Summary.<code>.md
// and the English versions are also installed as the demo vault's working files:
//   example-vault/Books/Library.base, example-vault/Templates/Book.md, example-vault/Books/Statistics.md,
//   example-vault/Books/Import.md,
//   example-vault/Books/Summaries.base, example-vault/Templates/Summary.md
import fs from 'node:fs';
import path from 'node:path';
import YAML from 'yaml';
import {
  COLOPHON,
  ROOT,
  VAULT,
  loadLocales,
  loadSettings,
  model,
  read,
  rel,
} from '../lib/common.mjs';
import { library } from './sources/library.mjs';
import { summaries } from './sources/summaries.mjs';

const args = process.argv.slice(2);
const check = args.includes('--check');
const option = (name) => {
  const index = args.indexOf(name);
  if (index < 0) return null;
  const value = args[index + 1];
  if (!value || value.startsWith('--')) {
    console.error(`error: ${name} needs a value`);
    process.exit(2);
  }
  return value;
};
const configArg = option('--config');
const outArg = option('--out');
if (configArg && !outArg) {
  console.error(
    'error: --config needs --out <folder>; the repository files are generated from the default config.json only',
  );
  process.exit(2);
}
if (outArg && !configArg) {
  console.error('error: --out is only used together with --config');
  process.exit(2);
}

const { settings, problems } = loadSettings(configArg ? path.resolve(configArg) : undefined);
if (problems.length) {
  for (const problem of problems) console.error(`error: ${problem}`);
  process.exit(1);
}

const locales = loadLocales();
const outputs = new Map();
const localizedDir = outArg ? path.resolve(outArg) : path.join(COLOPHON, 'localized');

const BASE_HEADER = (code) =>
  `# Generated by tools/build/build-localized.mjs from tools/build/sources/library.mjs, Colophon/config.json and Colophon/locales/${code}.json. Do not edit by hand.\n`;

const render = (source, t, values) =>
  source
    .replace(/\{\{t:([\w.]+)\}\}/g, (_, key) => t(key))
    .replace(/\{\{config:(\w+)\}\}/g, (_, name) => values[name]);

for (const [code, messages] of Object.entries(locales)) {
  const lookup = (key) => {
    const value = messages[key] ?? locales.en[key];
    return typeof value === 'string' ? value : undefined;
  };
  const t = (key) => {
    const value = messages[key] ?? locales.en[key];
    if (typeof value !== 'string') throw new Error(`${code}: "${key}" is not a plain string`);
    return value;
  };
  const catalog = model.catalog(settings, code, lookup);

  const base = library(t, catalog);
  const names = base.views.map((v) => v.name);
  const duplicate = names.find((n, i) => names.indexOf(n) !== i);
  if (duplicate) throw new Error(`${code}: two Library views are both called "${duplicate}"`);
  const baseText = BASE_HEADER(code) + YAML.stringify(base, { lineWidth: 0 });
  outputs.set(path.join(localizedDir, `Library.${code}.base`), baseText);

  outputs.set(
    path.join(localizedDir, `Summaries.${code}.base`),
    BASE_HEADER(code).replace('library.mjs', 'summaries.mjs') +
      YAML.stringify(summaries(t, catalog), { lineWidth: 0 }),
  );

  const values = { defaultStatus: catalog.keysOfKind('planned')[0] };
  const book = render(read(path.join(ROOT, 'tools/build/sources/Book.md')), t, values);
  const statistics = render(read(path.join(ROOT, 'tools/build/sources/Statistics.md')), t, values);
  outputs.set(path.join(localizedDir, `Book.${code}.md`), book);
  outputs.set(path.join(localizedDir, `Statistics.${code}.md`), statistics);
  const importPage = render(read(path.join(ROOT, 'tools/build/sources/Import.md')), t, values);
  outputs.set(path.join(localizedDir, `Import.${code}.md`), importPage);
  const summary = render(read(path.join(ROOT, 'tools/build/sources/Summary.md')), t, values);
  outputs.set(path.join(localizedDir, `Summary.${code}.md`), summary);

  if (code === 'en' && !outArg) {
    outputs.set(path.join(VAULT, 'Books', 'Library.base'), baseText);
    outputs.set(path.join(VAULT, 'Templates', 'Book.md'), book);
    outputs.set(path.join(VAULT, 'Books', 'Statistics.md'), statistics);
    outputs.set(path.join(VAULT, 'Books', 'Import.md'), importPage);
    outputs.set(
      path.join(VAULT, 'Books', 'Summaries.base'),
      outputs.get(path.join(localizedDir, 'Summaries.en.base')),
    );
    outputs.set(path.join(VAULT, 'Templates', 'Summary.md'), summary);
  }
}

// Files in localized/ that no longer belong to any language are stale (default mode only: a custom
// output folder may hold other files).
const stale =
  !outArg && fs.existsSync(localizedDir)
    ? fs
        .readdirSync(localizedDir)
        .map((f) => path.join(localizedDir, f))
        .filter((f) => !outputs.has(f))
    : [];

let problemCount = 0;
for (const [file, content] of outputs) {
  const current = fs.existsSync(file) ? read(file) : null;
  if (current === content) continue;
  if (check) {
    console.error(
      `error: ${rel(file)} is ${current === null ? 'missing' : 'out of date'}; run "npm run build"`,
    );
    problemCount++;
  } else {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, content);
    console.log(`wrote ${rel(file)}`);
  }
}
for (const file of stale) {
  if (check) {
    console.error(`error: ${rel(file)} is stale; run "npm run build"`);
    problemCount++;
  } else {
    fs.rmSync(file);
    console.log(`removed ${rel(file)}`);
  }
}

if (check) {
  if (problemCount) process.exitCode = 1;
  else console.log(`localized files: ok (${outputs.size} files)`);
}
